from pathlib import Path
import hashlib
for label, filename in (("receiver","servercore_bounded_host_receiver.py"),("writer","servercore_service_deploy_socket.py"),("sink","servercore_result_sink.py")):
    runtime=Path("/app/scripts") / filename
    checkout=Path("/home/admin1/server-core/scripts") / filename
    def audit(path):
        if not path.is_file():
            return {"exists": False}
        text=path.read_text(encoding="utf-8")
        return {"exists": True, "hash16": hashlib.sha256(text.encode()).hexdigest()[:16], "truncate16000": "[:16000]" in text or "16000" in text, "truncate1000": "[:1000]" in text or "1000" in text, "host_sink_fail_guard": 'request["command_id"] in {"dev.job", "host.command"}' in text}
    print(label, "runtime",audit(runtime),"checkout",audit(checkout))
